contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _valSet, uint _valAfter) public payable {
        require(_valSet != _valAfter);
        c.SetMinSum(_valSet); if (__ESBMC_reverted()) return;
        require(c.MinSum() == _valSet);

        c.Initialized(); if (__ESBMC_reverted()) return;
        require(c.MinSum() == _valSet);

        bool reverted;
        c.SetMinSum(_valAfter); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && c.MinSum() == _valSet);
    }

    receive() external payable {}
}

