pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _valSet, uint256 _valAfter) internal {
        vm.assume(_valSet != _valAfter);
        try c.SetMinSum(_valSet) {} catch { return; }
        _valSet = c.MinSum();
        try c.Initialized() {} catch { return; }
        _valSet = c.MinSum();
        bool reverted;
        try c.SetMinSum(_valAfter) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.MinSum() == _valSet);
    }

    function testFuzz_run(uint256 _valSet, uint256 _valAfter) public {
        _run(_valSet, _valAfter);
    }

    receive() external payable {}
}
